package org.com.sharekhan.analysis;
import org.junit.jupiter.api.Test;
import org.com.sharekhan.service.SharekhanHistoricalService.HistoricalCandle;
import java.time.*;import java.math.*;import java.util.*;
import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class HammerResearchTest {
 final LocalDate day=LocalDate.of(2026,10,30);final SwingSessions calendar=new SwingSessions();
 List<HistoricalCandle> bars(boolean setup){
  var rows=new ArrayList<HistoricalCandle>();LocalDate d=day;
  while(rows.size()<220){if(d.getDayOfWeek().getValue()<6&&(!calendar.supported(d)||calendar.regular(d)))rows.add(new HistoricalCandle(d,LocalTime.MIDNIGHT,90,91,89,90,3_000_000L));d=d.minusDays(1);}Collections.reverse(rows);
  if(setup){for(int i=160;i<219;i++)rows.set(i,new HistoricalCandle(rows.get(i).date(),LocalTime.MIDNIGHT,115,116,114,115,3_000_000L));rows.set(209,new HistoricalCandle(rows.get(209).date(),LocalTime.MIDNIGHT,125,130,120,125,3_000_000L));rows.set(219,new HistoricalCandle(day,LocalTime.MIDNIGHT,115,117,110,116,6_000_000L));}return rows;
 }
 StockDailyHistoryStore.Saved saved(String symbol,String id,boolean setup){return new StockDailyHistoryStore.Saved(symbol,id,new BigDecimal(".05"),Instant.parse("2026-11-01T12:00:00Z"),bars(setup));}
 HammerResearchService service(SavedDailyAnalysis daily){return new HammerResearchService(daily,calendar,Clock.fixed(Instant.parse("2026-11-01T17:00:00Z"),StockAnalysisService.IST));}
 HammerResearchService.Row eval(List<HistoricalCandle> rows){return service(mock(SavedDailyAnalysis.class)).evaluate(new StockDailyHistoryStore.Saved("DEMO","10",new BigDecimal(".05"),Instant.now(),rows),day,calendar.next(day));}
 @Test void previouslyStrongHammerHasEvidenceAndWorstEntrySellExits(){var r=eval(bars(true));assertThat(r.status()).isEqualTo("CONDITIONAL_BUY");assertThat(r.evidence().hammer()).isTrue();assertThat(r.evidence().undercutReclaim()).isTrue();assertThat(r.evidence().sessionsSinceHigh()).isEqualTo(10);assertThat(r.score()).isBetween(70,85);var p=r.plan();assertThat(p.entry()).isGreaterThan(117);assertThat(p.maxEntry()).isGreaterThan(p.entry());assertThat(p.stop()).isLessThan(110);assertThat(p.riskPerShare()).isCloseTo(p.maxEntry()-p.stop(),within(.00001));assertThat(p.target1()).isGreaterThanOrEqualTo(p.maxEntry()+2*p.riskPerShare());assertThat(p.target2()).isGreaterThanOrEqualTo(p.maxEntry()+3*p.riskPerShare());assertThat(p.riskPercent()).isLessThanOrEqualTo(8);}
 @Test void genericHammerWithoutPriorStrengthIsFiltered(){var rows=bars(false);rows.set(219,new HistoricalCandle(day,LocalTime.MIDNIGHT,88,90,84,89,6_000_000L));var r=eval(rows);assertThat(r.evidence().hammer()).isTrue();assertThat(r.plan()).isNull();assertThat(r.reason()).contains("Prior momentum not established");}
 @Test void badGeometryAndLowLiquidityAreNotCandidates(){var rows=bars(true);rows.set(219,new HistoricalCandle(day,LocalTime.MIDNIGHT,110,117,110,116,6_000_000L));assertThat(eval(rows).reason()).contains("Hammer geometry failed");rows=bars(true);for(int i=0;i<219;i++){var b=rows.get(i);rows.set(i,new HistoricalCandle(b.date(),b.time(),b.open(),b.high(),b.low(),b.close(),100_000L));}assertThat(eval(rows).reason()).contains("Liquidity");assertThat(eval(rows).plan()).isNull();}
 @Test void flatAndDojiAreFiniteAndNeverInventPrices(){var rows=bars(true);rows.set(219,new HistoricalCandle(day,LocalTime.MIDNIGHT,115,115,115,115,6_000_000L));assertThat(eval(rows).plan()).isNull();rows.set(219,new HistoricalCandle(day,LocalTime.MIDNIGHT,116,117,110,116,6_000_000L));var r=eval(rows);assertThat(r.evidence().wickToBody()).isEqualTo(999);assertThat(r.score()).isLessThanOrEqualTo(85);}
 @Test void wideWorstEntryRiskAndFiveRupeeTicksFailConservatively(){var rows=bars(true);rows.set(219,new HistoricalCandle(day,LocalTime.MIDNIGHT,115,117,100,116,6_000_000L));assertThat(eval(rows).reason()).contains("Worst-entry risk");var input=saved("DEMO","10",true);var r=service(mock(SavedDailyAnalysis.class)).evaluate(new StockDailyHistoryStore.Saved(input.symbol(),input.securityId(),new BigDecimal("5"),input.capturedAt(),input.candles()),day,calendar.next(day));assertThat(r.status()).isNotEqualTo("UNAVAILABLE");assertThat(r.plan()).isNull();}
 @Test void futureBarsDoNotChangeAsOfResults(){var rows=bars(true);var before=eval(rows);rows.add(new HistoricalCandle(day.plusDays(1),LocalTime.MIDNIGHT,1,2000,1,1000,20_000_000L));assertThat(eval(rows)).isEqualTo(before);}
 @Test void staleShortMissingConflictingAndDiscontinuousDataAreUnavailable(){var rows=bars(true);assertThat(eval(rows.subList(1,220)).status()).isEqualTo("UNAVAILABLE");assertThat(eval(rows.subList(0,219)).status()).isEqualTo("UNAVAILABLE");rows.remove(210);rows.add(0,new HistoricalCandle(LocalDate.of(2025,1,2),LocalTime.MIDNIGHT,90,91,89,90,3_000_000L));assertThat(eval(rows).reason()).contains("Missing recent");rows=bars(true);rows.add(new HistoricalCandle(day,LocalTime.MIDNIGHT,115,119,110,116,6_000_000L));assertThat(eval(rows).status()).isEqualTo("UNAVAILABLE");rows=bars(true);var b=rows.get(100);rows.set(100,new HistoricalCandle(b.date(),b.time(),200,202,198,200,3_000_000L));assertThat(eval(rows).reason()).contains("corporate-action");}
 SavedDailyAnalysis mocked(boolean strong,boolean collision){var daily=mock(SavedDailyAnalysis.class);var members=new ArrayList<StockDailyHistoryStore.Member>();for(int i=0;i<200;i++){String symbol="DEMO"+i;members.add(new StockDailyHistoryStore.Member(symbol,"INE"+i,day));when(daily.read(symbol,day)).thenReturn(saved(symbol,collision?"10":String.valueOf(100+i),strong||i==0));}when(daily.members()).thenReturn(members);return daily;}
 @Test void marketGateWithholdsPlansButPreservesEvidenceAndPreGateCount(){var r=service(mocked(false,false)).report();assertThat(r.status()).isEqualTo("MARKET_CAUTION");assertThat(r.entryCandidatesBeforeMarketGate()).isEqualTo(1);assertThat(r.stocks()).allMatch(s->s.plan()==null);assertThat(r.stocks()).anyMatch(s->s.status().equals("WATCH_ONLY")&&s.evidence().hammer());}
 @Test void readyAndCachedReportOnlyReadsSavedData(){var d=mocked(true,false);var s=service(d);var r=s.report();assertThat(r.status()).isEqualTo("READY");assertThat(r.stocks()).allMatch(v->v.plan()!=null);assertThat(s.report()).isSameAs(r);verify(d,times(1)).read("DEMO0",day);}
 @Test void collisionsAndIncompleteUniverseBlockEntries(){var r=service(mocked(true,true)).report();assertThat(r.status()).isEqualTo("DATA_INCOMPLETE");assertThat(r.coveredCount()).isZero();assertThat(r.stocks()).allMatch(s->s.plan()==null);var d=mocked(true,false);var partial=d.members().subList(0,10);when(d.members()).thenReturn(partial);assertThat(service(d).report().status()).isEqualTo("DATA_INCOMPLETE");}
}
